<?php require_once __DIR__.'/config/auth.php';$pageTitle='Dashboard';$in=$pdo->query("SELECT COALESCE(SUM(nominal),0) FROM transaksi WHERE jenis='pemasukan'")->fetchColumn();$out=$pdo->query("SELECT COALESCE(SUM(nominal),0) FROM transaksi WHERE jenis='pengeluaran'")->fetchColumn();$bal=$in-$out;$recent=$pdo->query("SELECT t.*,k.nama kategori FROM transaksi t JOIN kategori k ON k.id=t.kategori_id ORDER BY t.tanggal DESC,t.id DESC LIMIT 10")->fetchAll();function rp($n){return 'Rp '.number_format($n,0,',','.');}include __DIR__.'/partials/header.php';?><div class="row g-3"><div class="col-md-4"><div class="card p-4"><div>Total Pemasukan</div><h2 class="income"><?=rp($in)?></h2></div></div><div class="col-md-4"><div class="card p-4"><div>Total Pengeluaran</div><h2 class="expense"><?=rp($out)?></h2></div></div><div class="col-md-4"><div class="card p-4"><div>Saldo</div><h2 class="balance"><?=rp($bal)?></h2></div></div></div><div class="card p-4 mt-4"><h5>Transaksi Terbaru</h5><div class="table-responsive"><table class="table"><thead><tr><th>Tanggal</th><th>Jenis</th><th>Kategori</th><th>Keterangan</th><th>Nominal</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=$r['tanggal']?></td><td><?=ucfirst($r['jenis'])?></td><td><?=htmlspecialchars($r['kategori'])?></td><td><?=htmlspecialchars($r['keterangan']?:'-')?></td><td class="<?=$r['jenis']==='pemasukan'?'income':'expense'?> fw-bold"><?=rp($r['nominal'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/partials/footer.php';?>